{
  "technical_and_design_decisions": [
    "For U1, ZK metadata namespace isolation will be implemented via automatic path prefixing based on tenant profile, using existing Spring ZK client integration without modifying core ZK client logic.",
    "For U2, Admin server authentication will use Spring Security's built-in form-based login, with credentials stored only in HTTP session memory (no persistent storage) to eliminate password logging risks.",
    "For U3, the GitFlow branching model will be used, with a dedicated 'maintenance' branch created from the current minor release tag, protected to only allow merge requests for patch/minor version changes.",
    "For U4, deprecated function cleanup will leverage existing static code analysis (SonarQube) tooling to identify unused and deprecated code, with removal limited to non-public API deprecated functions to avoid breaking external consumers.",
    "For U5, the initial spike will evaluate both direct ZK access from xd-shell and a load balancer-mediated approach, with the selected implementation using a dedicated ZK node to store the dynamic Tomcat admin port for xd-shell to discover.",
    "For U6, Kafka client upgrade will be limited to the 0.9.x consumer rewrite, with no changes to the existing producer API or message bus contract to minimize regression risk.",
    "For U7, Motion-JPEG streaming will be implemented using a platform-agnostic OpenCV JNI wrapper to avoid platform compatibility issues, with the streaming endpoint integrated into the existing data ingest pipeline.",
    "For U8, the message rate enable/disable flag will be added to the existing servers.yml configuration schema, with both backend API and frontend Admin-UI components modified to respect the flag."
  ],
  "assumptions": [
    "The existing codebase is built on Spring Framework 6.0+ and Java 17+, so all new features are compatible with the existing runtime environment.",
    "ZooKeeper is already deployed and integrated into the system for metadata storage, so no new ZK cluster provisioning or core ZK client changes are required.",
    "The existing xd-shell and Admin server have extensible Spring Security and connection logic that can be modified without full rewrites.",
    "Pre-built OpenCV native libraries are available for all target deployment platforms (Linux, Windows, macOS) via the JNI wrapper, eliminating the need for custom platform-specific native builds.",
    "The Kafka 0.9 consumer rewrite only modifies the consumer client interface, with no breaking changes to the existing message format or producer API.",
    "The existing CI/CD pipeline already supports GitFlow branching patterns, so maintenance branch setup only requires configuration changes rather than new pipeline development.",
    "All user stories are independent with no cross-cutting dependencies that would require additional coordination or integration effort beyond the listed activities.",
    "The existing test suite has sufficient coverage for the modules being modified, so no new test infrastructure is required."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Design ZK tenant namespace scoping logic",
      "activity_description": "Design the mapping between tenant profiles and ZooKeeper path prefixes to ensure metadata isolation between tenants, with no cross-tenant access allowed.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement ZK client namespace wrapper",
      "activity_description": "Modify the existing ZooKeeper client wrapper to automatically prepend tenant-specific namespace prefixes to all ZK path operations, ensuring transparent isolation for existing code.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A3",
      "activity_name": "Test tenant namespace isolation",
      "activity_description": "Write and run unit and integration tests to verify that tenants can only access their own namespaced metadata, and cross-tenant access is blocked.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Design Admin server authentication flow",
      "activity_description": "Design the form-based login flow for the Admin server using Spring Security, with no persistent credential storage to avoid password logging risks.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement Admin server login functionality",
      "activity_description": "Implement the login endpoint, credential validation, and session management for the Admin server, ensuring credentials are only stored in temporary HTTP sessions and never logged or persisted.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "Test Admin server authentication",
      "activity_description": "Write and run security tests to verify invalid credentials are rejected, valid credentials grant access, and no credentials are exposed in logs or persistent storage.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A7",
      "activity_name": "Configure GitFlow maintenance branch",
      "activity_description": "Create the dedicated 'maintenance' branch from the latest minor release tag in version control, and set up branch protection rules to only allow merge requests for patch/minor version changes.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A8",
      "activity_name": "Document maintenance branch workflow",
      "activity_description": "Create documentation for the development team outlining when to use the maintenance branch vs master, and the PR/merge process for maintenance branch changes.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A9",
      "activity_name": "Identify deprecated and unused code",
      "activity_description": "Run static code analysis (SonarQube) scans of the module registry, Shell, and Admin-UI codebases to generate a list of deprecated functions and unused code for removal.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A10",
      "activity_name": "Remove deprecated and unused code",
      "activity_description": "Delete deprecated module definition download APIs and all unused code identified in the scan, ensuring no broken references remain in the codebase.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A11",
      "activity_name": "Validate cleanup with test suite",
      "activity_description": "Run the full unit, integration, and system test suite to verify that the code cleanup has not introduced any regressions.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A12",
      "activity_name": "Conduct xd-shell admin server access spike",
      "activity_description": "Research and test both direct ZK access from xd-shell and load balancer-mediated approaches for connecting to the dynamic admin server port, document the recommended approach.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A13",
      "activity_name": "Implement ZK port storage for admin server",
      "activity_description": "Modify the admin server startup logic to write the dynamically generated random Tomcat port to a fixed, well-known ZooKeeper node on boot.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A14",
      "activity_name": "Modify xd-shell to discover admin server port",
      "activity_description": "Update xd-shell connection logic to read the admin server port from the dedicated ZK node instead of using a hardcoded value, enabling dynamic connection to the running admin server.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A15",
      "activity_name": "Test xd-shell port discovery flow",
      "activity_description": "Write and run tests to verify the admin server correctly writes its port to ZK on startup, and xd-shell can successfully connect to the admin server using the discovered port.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A16",
      "activity_name": "Upgrade Kafka client dependencies",
      "activity_description": "Update all Maven/Gradle dependencies to use Kafka 0.9.x client libraries, resolving any version conflicts with existing dependencies.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A17",
      "activity_name": "Update tests for new Kafka consumer API",
      "activity_description": "Modify existing Kafka-related test code to use the new 0.9 consumer rewrite API, updating test configurations and consumer setup logic as needed.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A18",
      "activity_name": "Fix failing Kafka consumer tests",
      "activity_description": "Debug and fix all failing tests related to the Kafka 0.9 consumer rewrite, ensuring all Kafka-related tests pass with the new client version.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A19",
      "activity_name": "Conduct Motion-JPEG streaming feasibility spike",
      "activity_description": "Research Motion-JPEG format specifications, test streaming performance and compatibility with the existing data ingest pipeline, and document feasibility findings.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A20",
      "activity_name": "Integrate OpenCV JNI wrapper for frame processing",
      "activity_description": "Add the platform-agnostic OpenCV JNI wrapper dependency, implement video frame capture and processing logic for facial detection, and test functionality across target deployment platforms.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A21",
      "activity_name": "Implement Motion-JPEG streaming endpoint",
      "activity_description": "Create an HTTP endpoint that streams captured video frames in Motion-JPEG format, integrated with the existing data ingest pipeline for downstream predictive analytics processing.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A22",
      "activity_name": "Test Motion-JPEG streaming functionality",
      "activity_description": "Write and run tests to verify the streaming endpoint outputs valid Motion-JPEG frames, and frame processing works correctly for the facial detection use case.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A23",
      "activity_name": "Add message rate config parameter to servers.yml",
      "activity_description": "Add the 'messageRates.enabled' boolean configuration parameter to the servers.yml schema and default configuration, with validation to ensure correct value types.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A24",
      "activity_name": "Modify backend cluster view logic",
      "activity_description": "Update the backend cluster view API and metric collection logic to skip gathering and returning message rate metrics when the 'messageRates.enabled' flag is set to false.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A25",
      "activity_name": "Modify Admin-UI cluster view",
      "activity_description": "Update the Admin-UI cluster view frontend components to conditionally render message rate metrics only when the 'messageRates.enabled' configuration flag is enabled.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A26",
      "activity_name": "Test message rate config functionality",
      "activity_description": "Write and run tests to verify that disabling the 'messageRates.enabled' flag hides message rates in the cluster view, enabling shows them, and the default value works as expected.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 39
  }
}

